/* Narrow screens have no horizontal room to give away, so the key returns to a
   strip under the grid — same panel, same button, stacked instead of beside. */
@media (max-width: 720px) {
  .board-main { flex-direction: column; }
  .cal-legend {
    flex: 0 0 auto;
    margin-left: 0; padding-left: 0;
    margin-top: 14px; padding-top: 12px;
    border-left: none; border-top: 1px solid var(--line);
  }
  .cal-legend .legend { flex-direction: row; flex-wrap: wrap; gap: 10px 16px; }
}

/* ============ Allocate / itinerary (the plan panel) ============ */
.plan-card { padding: 28px 28px 26px; margin-top: 22px; }
.plan-head {
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 20px 28px; flex-wrap: wrap;
---
