/* Headers that carry the primary nav become three columns instead, so "Now /
   Plan" sits on the page's centre line rather than in the middle of whatever
   space the logo and the header icons happen to leave over (those two are
   never the same width, so auto margins put the nav off-centre). Legal pages
   have no nav and keep the plain two-item flex row above. */
.header-inner:has(.main-nav) {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
}
.header-inner:has(.main-nav) > :first-child { justify-self: start; }
.header-inner:has(.main-nav) > :last-child { justify-self: end; }

